<?php
declare(strict_types=1);
require_once __DIR__.'/operations.php';

function finance_schema(): void {
    $text=db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?'LONGTEXT':'TEXT';
    foreach([
        'CREATE TABLE IF NOT EXISTS atelier_finance_sequences (structure_id VARCHAR(32) NOT NULL,year INTEGER NOT NULL,value INTEGER NOT NULL,PRIMARY KEY(structure_id,year))',
        "CREATE TABLE IF NOT EXISTS atelier_invoices (id VARCHAR(32) PRIMARY KEY,structure_id VARCHAR(32) NOT NULL,source_id VARCHAR(100) NOT NULL,number VARCHAR(40) NOT NULL,issued VARCHAR(10) NOT NULL,data $text NOT NULL,UNIQUE(structure_id,source_id),UNIQUE(structure_id,number))",
        "CREATE TABLE IF NOT EXISTS atelier_payments (id VARCHAR(32) PRIMARY KEY,structure_id VARCHAR(32) NOT NULL,invoice_id VARCHAR(32) NOT NULL,provider_ref VARCHAR(150) NOT NULL,data $text NOT NULL,UNIQUE(structure_id,provider_ref))",
        'CREATE TABLE IF NOT EXISTS atelier_checkouts (id VARCHAR(32) PRIMARY KEY,structure_id VARCHAR(32) NOT NULL,invoice_id VARCHAR(32) NOT NULL,amount BIGINT NOT NULL,status VARCHAR(20) NOT NULL,session_id VARCHAR(150),url TEXT,created_at BIGINT NOT NULL,expires_at BIGINT NOT NULL)',
    ] as $sql)db()->exec($sql);
}
function finance_settings(string $structure): array {return config()['finance'][$structure]??[];}
function finance_lock(string $structure): void {query('UPDATE atelier_workspaces SET revision=revision WHERE structure_id=?',[$structure]);}
function finance_rows(string $table,string $structure): array {if(!in_array($table,['atelier_invoices','atelier_payments'],true))fail(500,'Table inconnue.');return array_map(fn($r)=>json_decode($r['data'],true,32,JSON_THROW_ON_ERROR),query("SELECT data FROM $table WHERE structure_id=? ORDER BY id",[$structure])->fetchAll());}
function finance_totals(array $lines): array {
    $net=0;$tax=0;
    foreach(op_list($lines,50) as $l){if(!is_array($l))fail(422,'Ligne de facture invalide.');clean_text($l['label']??null,500,'prestation',true);$q=$l['quantityMilli']??null;$unit=$l['unitCents']??null;$rate=$l['vatBps']??null;if(!is_int($q)||$q<1||$q>99999999||!is_int($rate)||$rate<0||$rate>10000)fail(422,'Quantité ou TVA invalide.');op_money($unit);$amount=intdiv($unit*$q+500,1000);if($amount>10000000000)fail(422,'Ligne trop élevée.');$vat=intdiv($amount*$rate+5000,10000);$net+=$amount;$tax+=$vat;if($net+$tax>10000000000)fail(422,'Total trop élevé.');}
    return ['netCents'=>$net,'taxCents'=>$tax,'totalCents'=>$net+$tax];
}
function finance_profile(array $p): array {foreach(['name'=>250,'legalForm'=>250,'address'=>1000,'siren'=>9,'vatId'=>40,'registration'=>500,'exemption'=>1000,'paymentTerms'=>2000,'lateTerms'=>2000,'bankInstructions'=>1500] as $key=>$max)$p[$key]=clean_text($p[$key]??'',$max,$key);if($p['siren']!==''&&!preg_match('/^\d{9}$/D',$p['siren']))fail(422,'SIREN invalide.');return $p;}
function finance_validate_draft(array $d,array $state): array {
    clean_text($d['id']??null,100,'brouillon',true);foreach(['title'=>250,'customerName'=>250,'customerAddress'=>1000,'customerSiren'=>9,'customerVat'=>40,'purchaseOrder'=>250,'notes'=>2000] as $key=>$max)clean_text($d[$key]??'',$max,$key,in_array($key,['title','customerName'],true));
    if(($d['customerSiren']??'')!==''&&!preg_match('/^\d{9}$/D',$d['customerSiren']))fail(422,'SIREN client invalide.');op_enum($d['customerType']??null,['business','public','consumer']);op_date($d['serviceDate']??'');op_date($d['due']??'');
    if(!empty($d['productionId'])&&!in_array($d['productionId'],array_column($state['productions']??[],'id'),true))fail(422,'Production de facture absente.');if(!empty($d['contactId'])&&!in_array($d['contactId'],array_column($state['contacts'],'id'),true))fail(422,'Client de facture absent.');
    $lines=op_list($d['lines']??null,50);if(!$lines)fail(422,'Facture sans prestation.');$totals=finance_totals($lines);foreach($totals as $key=>$n)if(($d[$key]??null)!==$n)fail(422,'Totaux de facture incohérents.');return $d;
}
function validate_finance_workspace(array $state): void {
    if(!isset($state['finance']))return;$f=$state['finance'];if(!is_array($f))fail(422,'Gestion financière invalide.');finance_profile($f['profile']??[]);
    foreach(op_rows($f['drafts']??[],500) as $d)finance_validate_draft($d,$state);
    foreach(op_rows($f['engagements']??[],500) as $e){clean_text($e['name']??null,250,'personne / structure',true);op_enum($e['route']??null,['guso','payroll','supplier','author','expenses','volunteer']);foreach(['role'=>250,'employer'=>250,'place'=>500,'units'=>40,'note'=>2000] as $key=>$max)clean_text($e[$key]??'',$max,$key);op_date($e['from']??'',true);op_date($e['to']??'',true);if($e['to']<$e['from'])fail(422,'Dates de rémunération invalides.');if(!empty($e['productionId'])&&!in_array($e['productionId'],array_column($state['productions']??[],'id'),true))fail(422,'Production de rémunération absente.');foreach(['grossCents','netCents','contributionsCents','costCents'] as $k)op_money($e[$k]??null,true);if($e['route']==='volunteer'&&array_sum(array_map(fn($k)=>$e[$k]??0,['grossCents','netCents','contributionsCents','costCents']))>0)fail(422,'Bénévolat avec rémunération incompatible.');foreach(['mainShow','live','professional'] as $k)op_enum($e[$k]??null,['yes','no','unknown']);if($e['route']==='guso'&&($e['mainShow']==='yes'||$e['live']==='no'||$e['professional']==='no'))fail(422,'Circuit GUSO incompatible avec les réponses.');foreach(['checks','refs'] as $k)if(!is_array($e[$k]??null)||count($e[$k])>30)fail(422,'Suivi de déclaration invalide.');foreach($e['checks'] as $key=>$value)if(!is_bool($value)||($value&&empty($e['refs'][$key])))fail(422,'Justificatif de déclaration manquant.');foreach($e['refs'] as $ref)clean_text($ref,500,'référence');}
    // Demo-only issued documents and receipts are never accepted into a shared workspace.
    if(!empty($f['demoInvoices'])||!empty($f['demoPayments']))fail(422,'Les exemples financiers locaux ne peuvent pas devenir des documents officiels.');
}
function finance_get(string $structure,string $actor): array {membership($structure,$actor);$c=finance_settings($structure);return ['invoices'=>finance_rows('atelier_invoices',$structure),'payments'=>finance_rows('atelier_payments',$structure),'enabled'=>($c['issue_enabled']??false)===true,'checkout'=>finance_checkout_ready($c)];}
function finance_checkout_ready(array $c): bool {return !empty($c['stripe_secret'])&&!empty($c['stripe_webhook_secret']);}
function finance_find(string $structure,string $id): array {$r=query('SELECT data FROM atelier_invoices WHERE structure_id=? AND id=?',[$structure,$id])->fetch();if(!$r)fail(404,'Facture introuvable.');return json_decode($r['data'],true,32,JSON_THROW_ON_ERROR);}
function finance_balance(string $structure,array $invoice): array {$credits=0;$paid=0;foreach(finance_rows('atelier_invoices',$structure) as $i)if(($i['creditOf']??'')===$invoice['id'])$credits+=$i['totalCents'];foreach(finance_rows('atelier_payments',$structure) as $p)if($p['invoiceId']===$invoice['id'])$paid+=($p['direction']==='receipt'?1:-1)*$p['amountCents'];$balance=$invoice['totalCents']-$credits-$paid;return ['due'=>max(0,$balance),'refundDue'=>max(0,-$balance)];}
function finance_number(string $structure): array {
    $today=(new DateTimeImmutable('now',new DateTimeZone('Europe/Paris')))->format('Y-m-d');$year=(int)substr($today,0,4);$last=query('SELECT issued FROM atelier_invoices WHERE structure_id=? ORDER BY issued DESC LIMIT 1',[$structure])->fetch();if($last&&$last['issued']>$today)fail(409,'Horloge serveur antérieure à la dernière émission.');
    $row=query('SELECT value FROM atelier_finance_sequences WHERE structure_id=? AND year=?',[$structure,$year])->fetch();$next=($row?(int)$row['value']:0)+1;if($row)query('UPDATE atelier_finance_sequences SET value=? WHERE structure_id=? AND year=?',[$next,$structure,$year]);else query('INSERT INTO atelier_finance_sequences(structure_id,year,value) VALUES(?,?,?)',[$structure,$year,$next]);return ['number'=>'FAC-'.$year.'-'.str_pad((string)$next,6,'0',STR_PAD_LEFT),'issued'=>$today];
}
function finance_store_invoice(string $structure,array $row): array {query('INSERT INTO atelier_invoices(id,structure_id,source_id,number,issued,data) VALUES(?,?,?,?,?,?)',[$row['id'],$structure,$row['sourceId'],$row['number'],$row['issued'],json_encode($row,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);return $row;}
function finance_issue(string $structure,string $actor,string $draftId): array {
    membership($structure,$actor,true);if((finance_settings($structure)['issue_enabled']??false)!==true)fail(503,'Émission réelle non activée pour cette structure.');$pdo=db();$pdo->beginTransaction();try{finance_lock($structure);$prior=query('SELECT data FROM atelier_invoices WHERE structure_id=? AND source_id=?',[$structure,$draftId])->fetch();if($prior){$pdo->commit();return json_decode($prior['data'],true,32,JSON_THROW_ON_ERROR);}$s=read_workspace($structure,$actor)['state'];$f=$s['finance']??[];$d=null;foreach($f['drafts']??[] as $x)if($x['id']===$draftId)$d=$x;if(!$d)fail(404,'Brouillon absent de la dernière sauvegarde.');$d=finance_validate_draft($d,$s);$p=finance_profile($f['profile']??[]);
        foreach(['name','legalForm','address','siren','paymentTerms'] as $key)if(!$p[$key])fail(422,'Émetteur incomplet : '.$key);foreach(['customerAddress','due','serviceDate'] as $key)if(empty($d[$key]))fail(422,'Facture incomplète : '.$key);if($d['customerType']!=='consumer'&&empty($d['customerSiren']))fail(422,'SIREN client requis.');if($d['due']<$d['serviceDate']||$d['totalCents']<=0)fail(422,'Dates ou montant à corriger.');foreach($d['lines'] as $l)if(($l['vatBps']===0&&!$p['exemption'])||($l['vatBps']>0&&!$p['vatId']))fail(422,'Régime TVA incomplet.');if($d['customerType']==='business'&&!$p['lateTerms'])fail(422,'Conditions professionnelles de retard manquantes.');
        $row=[...$d,'id'=>uid(),'sourceId'=>$draftId,'kind'=>'invoice','issuer'=>$p,...finance_number($structure),'demo'=>false];unset($row['issuedId']);finance_store_invoice($structure,$row);audit($structure,$actor,'invoice.issued');$pdo->commit();return $row;
    }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function finance_credit(string $structure,string $actor,string $id): array {membership($structure,$actor,true);$pdo=db();$pdo->beginTransaction();try{finance_lock($structure);$source='credit:'.$id;$prior=query('SELECT data FROM atelier_invoices WHERE structure_id=? AND source_id=?',[$structure,$source])->fetch();if($prior){$pdo->commit();return json_decode($prior['data'],true,32,JSON_THROW_ON_ERROR);}$original=finance_find($structure,$id);if($original['kind']!=='invoice')fail(422,'Choisissez la facture d’origine.');finance_no_checkout($structure,$id);$row=[...$original,'id'=>uid(),'sourceId'=>$source,'kind'=>'credit','creditOf'=>$id,'creditNumber'=>$original['number'],...finance_number($structure)];finance_store_invoice($structure,$row);audit($structure,$actor,'invoice.credited');$pdo->commit();return $row;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
function finance_no_checkout(string $structure,string $invoice): void {$active=query("SELECT id FROM atelier_checkouts WHERE structure_id=? AND invoice_id=? AND status IN ('creating','open') LIMIT 1",[$structure,$invoice])->fetch();if($active)fail(409,'Un lien de paiement est encore actif. Vérifiez son état avant de modifier le solde.');}
function finance_store_payment(string $structure,array $row,string $providerRef): array {query('INSERT INTO atelier_payments(id,structure_id,invoice_id,provider_ref,data) VALUES(?,?,?,?,?)',[$row['id'],$structure,$row['invoiceId'],$providerRef,json_encode($row,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);return $row;}
function finance_reverse(string $structure,string $actor,string $id,string $reason): array {membership($structure,$actor,true);$reason=clean_text($reason,500,'motif de correction',true);$pdo=db();$pdo->beginTransaction();try{finance_lock($structure);$original=null;$prior=null;foreach(finance_rows('atelier_payments',$structure) as $r){if($r['id']===$id)$original=$r;if(($r['reversalOf']??'')===$id)$prior=$r;}if($prior){$pdo->commit();return $prior;}if(!$original||$original['origin']!=='manual'||isset($original['reversalOf']))fail(422,'Seule une écriture manuelle d’origine peut être contrepassée.');finance_no_checkout($structure,$original['invoiceId']);$row=[...$original,'id'=>uid(),'direction'=>$original['direction']==='receipt'?'refund':'receipt','reversalOf'=>$id,'date'=>(new DateTimeImmutable('now',new DateTimeZone('Europe/Paris')))->format('Y-m-d'),'reference'=>$reason];finance_store_payment($structure,$row,'reverse:'.$id);audit($structure,$actor,'payment.reversed');$pdo->commit();return $row;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
function finance_payment(string $structure,string $actor,array $v): array {membership($structure,$actor,true);$invoiceId=clean_text($v['invoiceId']??null,32,'facture',true);$direction=$v['direction']??'';op_enum($direction,['receipt','refund']);op_enum($v['method']??null,['transfer','card','cheque','cash','sepa','other']);$raw=clean_text($v['amount']??null,30,'montant',true);$raw=str_replace(["\u{00a0}","\u{202f}",' ',','],['','','','.'],$raw);if(!preg_match('/^\d{1,9}(\.\d{1,2})?$/D',$raw))fail(422,'Montant invalide.');[$whole,$dec]=array_pad(explode('.',$raw),2,'');$amount=(int)$whole*100+(int)str_pad($dec,2,'0');op_money($amount);op_date($v['date']??'',true);$reference=clean_text($v['reference']??'',500,'justificatif',true);$requestId=clean_text($v['requestId']??null,100,'identifiant de saisie',true);if(!preg_match('/^[a-zA-Z0-9-]{16,100}$/D',$requestId))fail(422,'Identifiant de règlement invalide.');$providerRef='manual:'.$requestId;
    $pdo=db();$pdo->beginTransaction();try{finance_lock($structure);$prior=query('SELECT data FROM atelier_payments WHERE structure_id=? AND provider_ref=?',[$structure,$providerRef])->fetch();if($prior){$row=json_decode($prior['data'],true,32,JSON_THROW_ON_ERROR);if($row['invoiceId']!==$invoiceId)fail(409,'Identifiant de règlement déjà utilisé.');$pdo->commit();return $row;}$invoice=finance_find($structure,$invoiceId);if($invoice['kind']!=='invoice')fail(422,'Règlement à lier à une facture.');finance_no_checkout($structure,$invoiceId);$b=finance_balance($structure,$invoice);if($amount<=0||$amount>$b[$direction==='receipt'?'due':'refundDue'])fail(422,'Montant supérieur au solde disponible.');$row=['id'=>uid(),'invoiceId'=>$invoiceId,'direction'=>$direction,'method'=>$v['method'],'amountCents'=>$amount,'date'=>$v['date'],'reference'=>$reference,'origin'=>'manual'];finance_store_payment($structure,$row,$providerRef);audit($structure,$actor,'payment.recorded');$pdo->commit();return $row;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
